  3371  static char *
  3372  pdf_sprint_encrypted_obj(fz_context *ctx, char *buf, size_t cap, size_t *len, pdf_obj *obj, int tight, int ascii, pdf_crypt *crypt, int num, int gen)
  3373  {
  3374          struct fmt fmt;
  3375
  3376          fmt.indent = 0;
  3377          fmt.col = 0;
  3378          fmt.sep = 0;
  3379          fmt.last = 0;
  3380
  3381          if (!buf || cap == 0)
  3382          {
  3383                  fmt.cap = 1024;
  3384                  fmt.buf = NULL;
  3385                  fmt.ptr = Memento_label(fz_malloc(ctx, fmt.cap), "fmt_buf");
  3386          }
  3387          else
  3388          {
  3389                  fmt.cap = cap;
  3390                  fmt.buf = buf;
  3391                  fmt.ptr = buf;
  3392          }
  3393
  3394          fmt.tight = tight;
  3395          fmt.ascii = ascii;
  3396          fmt.len = 0;
  3397          fmt.crypt = crypt;
  3398          fmt.num = num;
  3399          fmt.gen = gen;
  3400          fmt_obj(ctx, &fmt, obj);
  3401
  3402          fmt_putc(ctx, &fmt, 0);
  3403
  3404          return *len = fmt.len-1, fmt.ptr;
  3405  }
