  3413  void pdf_print_encrypted_obj(fz_context *ctx, fz_output *out, pdf_obj *obj, int tight, int ascii, pdf_crypt *crypt, int num, int gen)
  3414  {
  3415          char buf[1024];
  3416          char *ptr;
  3417          size_t n;
  3418
  3419          ptr = pdf_sprint_encrypted_obj(ctx, buf, sizeof buf, &n, obj, tight, ascii, crypt, num, gen);
  3420          fz_try(ctx)
  3421                  fz_write_data(ctx, out, ptr, n);
  3422          fz_always(ctx)
  3423                  if (ptr != buf)
  3424                          fz_free(ctx, ptr);
  3425          fz_catch(ctx)
  3426                  fz_rethrow(ctx);
  3427  }
