  3429  void pdf_print_obj(fz_context *ctx, fz_output *out, pdf_obj *obj, int tight, int ascii)
  3430  {
  3431          pdf_print_encrypted_obj(ctx, out, obj, tight, ascii, NULL, 0, 0);
